-- 为已执行过本期建表迁移的数据库补齐中文注释。
-- 原迁移中的注释用于全新数据库；本迁移仅修改元数据，可重复执行，不变更表结构或业务数据。

COMMENT ON TABLE "public"."interview_telemetry_event" IS '真人面试链路事件与通话质量日志；关联页面、服务端和 LiveKit 事件，保留会议快照以供删会后排查；按接收时间执行日志保留策略';
COMMENT ON COLUMN "public"."interview_telemetry_event"."id" IS '日志记录主键，与来源事件去重键独立';
COMMENT ON COLUMN "public"."interview_telemetry_event"."event_key" IS '来源事件去重键；与会议 ID、参与身份和事件来源组成唯一键，避免重复上报或回调重复入库';
COMMENT ON COLUMN "public"."interview_telemetry_event"."client_sequence" IS '同一次页面访问内递增的客户端事件序号；非客户端事件可为空';
COMMENT ON COLUMN "public"."interview_telemetry_event"."meeting_id" IS '关联真人面试会议 ID；保留快照，不因会议删除而级联清除';
COMMENT ON COLUMN "public"."interview_telemetry_event"."organization_id" IS '会议所属工作区 ID 快照';
COMMENT ON COLUMN "public"."interview_telemetry_event"."meeting_title" IS '事件记录时的会议标题快照，用于会议删除后的定位';
COMMENT ON COLUMN "public"."interview_telemetry_event"."room_name" IS 'LiveKit 房间业务名称，用于关联会议与房间事件';
COMMENT ON COLUMN "public"."interview_telemetry_event"."participant_identity" IS 'LiveKit 参与身份；候选人为 candidate_轮次ID，面试官为 interviewer_用户ID；房间级事件可为空字符串';
COMMENT ON COLUMN "public"."interview_telemetry_event"."participant_name" IS '参与者显示名称快照，未获取时为空';
COMMENT ON COLUMN "public"."interview_telemetry_event"."participant_role" IS '参与角色快照：candidate 候选人、host 主持人、interviewer 面试官、observer 旁听；未知时可为空';
COMMENT ON COLUMN "public"."interview_telemetry_event"."source" IS '事件来源：client 浏览器上报、server 业务服务端、livekit 已验签的 LiveKit 回调';
COMMENT ON COLUMN "public"."interview_telemetry_event"."type" IS '事件类型代码，如 page_opened 打开页面、token_issued 签发凭证、disconnected 断线、network_sample 通话质量采样、media_device_error 设备异常';
COMMENT ON COLUMN "public"."interview_telemetry_event"."visit_id" IS '页面访问实例 ID；关联同一次访问的指纹、操作及连接事件，刷新页面会重新生成';
COMMENT ON COLUMN "public"."interview_telemetry_event"."tab_id" IS '页面实例的标签页标识；独立随机生成，刷新或复制标签页会重新生成，不是浏览器原生标签页编号';
COMMENT ON COLUMN "public"."interview_telemetry_event"."attempt_id" IS '一次点击入会产生的连接尝试 ID；关联凭证签发与 RTC 会话，尚未尝试入会时可为空';
COMMENT ON COLUMN "public"."interview_telemetry_event"."room_sid" IS 'LiveKit 分配的房间实例 SID；房间重新创建时可能变化，与业务会议 ID 区分';
COMMENT ON COLUMN "public"."interview_telemetry_event"."participant_sid" IS 'LiveKit 分配的参与者连接 SID；用于定位具体连接实例，与参与身份区分';
COMMENT ON COLUMN "public"."interview_telemetry_event"."ip" IS '服务端从配置的可信反向代理请求头取得的 IP；无法可靠获取时为空，不直接信任客户端自报 IP';
COMMENT ON COLUMN "public"."interview_telemetry_event"."ip_source" IS 'IP 证据来源，如 trusted-proxy:请求头名；unavailable 表示请求 IP 无可靠来源，非请求事件可为空';
COMMENT ON COLUMN "public"."interview_telemetry_event"."user_agent" IS '服务端收到的浏览器 User-Agent，最多保留 512 字符；只能作为客户端特征线索';
COMMENT ON COLUMN "public"."interview_telemetry_event"."occurred_at" IS '来源记录的事件发生时间；客户端时间可能受设备时钟偏差影响';
COMMENT ON COLUMN "public"."interview_telemetry_event"."received_at" IS '服务端接收并入库的时间；用于稳定排序及日志保留清理';
COMMENT ON COLUMN "public"."interview_telemetry_event"."details" IS '事件扩展 JSON；按事件包含 browserId 浏览器存储标识、fingerprint 指纹、fingerprintVersion、网络质量指标、状态及错误原因；设备标识不是硬件序列号，不能单独据此认定同一人或作弊';

COMMENT ON TABLE "public"."studio_human_interview_reminder_delivery" IS '旧版按轮次发送的真人面试前十分钟 TG 提醒记录；保留历史查询和升级迁移，当前会议级提醒不再向本表写入';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."round_id" IS '关联真人面试轮次 ID；旧版外键随轮次删除级联清除';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."scheduled_at" IS '该次提醒对应的轮次预约时间快照；与轮次 ID、收件人键共同去重';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."recipient_key" IS '收件人去重键；已绑定时为 chat:聊天ID，未绑定时保留人员标识';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."chat_id" IS 'Telegram 私聊目标 chat ID；尚未绑定时为空';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."roles" IS '收件人通知角色快照 JSON 数组，如招聘人员、面试官、分配 ODC；同一人可兼任多个角色';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."status" IS '发送状态：sending 发送中、sent 已发送、failed 失败、unbound 未绑定 TG、skipped 已跳过';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."attempt_id" IS '本次领取发送任务的尝试 ID，用于避免过期尝试覆盖新发送结果';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."attempts" IS '已领取的发送尝试次数，初始为 0';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."created_at" IS '发送记录首次创建时间';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."last_attempt_at" IS '最近一次发送尝试或状态记录时间，用于失败重试与发送超时恢复';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."sent_at" IS '成功发送到 Telegram 的时间，未成功时为空';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_delivery"."error_code" IS '发送失败、未绑定或跳过的原因代码，正常时为空';

COMMENT ON TABLE "public"."studio_human_interview_reminder_schedule" IS '真人面试会议级 TG 提醒调度表；每场会议一条持久化待同步记录，驱动 BullMQ 延迟任务及故障补偿；会议删除后保留停用记录';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."meeting_id" IS '关联真人面试会议 ID，同时为本表主键；不建立级联删除外键';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."organization_id" IS '会议所属工作区 ID 快照';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."revision" IS '提醒排期版本；会议改期或启停状态变化时递增，用于区分旧任务并阻止过期提醒';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."scheduled_at" IS '当前版本的会议预约开始时间；提醒通常在此前十分钟执行，未排期时为空';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."active" IS '当前会议是否具备提醒调度资格；预约时间非空且会议状态为 scheduled 或 in_progress 时为真，取消、结束或删除时为假';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."queued_revision" IS '最近一次完成队列同步的排期版本；包括旧任务清理或停用同步，尚未同步时为空';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."next_sync_at" IS '下一次同步或补偿检查时间；Worker 按索引读取到期记录，为空表示无需继续同步';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."error_code" IS '最近一次队列同步错误代码，如 queue_sync_failed；无错误时为空';
COMMENT ON COLUMN "public"."studio_human_interview_reminder_schedule"."updated_at" IS '会议触发器最近更新提醒排期记录的时间';
COMMENT ON TABLE "public"."studio_human_interview_meeting_reminder_delivery" IS '当前会议级真人面试前十分钟 TG 提醒发送明细；按会议、排期版本和收件人去重，保存关联轮次、角色、发送结果及重试状态；删会后保留';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."meeting_id" IS '关联真人面试会议 ID；不随会议删除级联清除';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."revision" IS '本条发送记录对应的提醒排期版本，与调度表 revision 对应';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."recipient_key" IS '收件人去重键；已绑定时为 chat:聊天ID，未绑定时保留人员标识；同一会议和版本下唯一';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."round_ids" IS '该收件人有权接收的候选人面试轮次 ID 快照 JSON 数组，用于合并同场会议通知';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."scheduled_at" IS '发送时对应的会议预约开始时间快照';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."chat_id" IS 'Telegram 私聊目标 chat ID；未完成绑定时可为空';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."roles" IS '收件人通知角色快照 JSON 数组，如招聘人员、面试官、分配 ODC；同一聊天目标合并角色';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."status" IS '发送状态：sending 发送中、sent 已发送、failed 失败、unbound 未绑定 TG、skipped 已跳过';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."attempt_id" IS '最近一次领取发送任务的尝试 ID；回写结果时校验，防止过期 Worker 覆盖当前尝试';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."attempts" IS '已领取的发送尝试次数，初始为 0；当前每位收件人每个排期版本最多尝试三次';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."created_at" IS '该会议、排期版本和收件人组合首次建立发送记录的时间';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."last_attempt_at" IS '最近一次领取发送任务或记录未绑定状态的时间；用于重试间隔及发送超时判断';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."sent_at" IS '成功发送到 Telegram 的时间，未成功时为空';
COMMENT ON COLUMN "public"."studio_human_interview_meeting_reminder_delivery"."error_code" IS '发送失败或跳过原因代码，如 telegram_not_bound；成功时清空';
COMMENT ON FUNCTION "public"."sync_human_interview_reminder_schedule"() IS '在会议事务内同步提醒排期版本和启停状态，并发送提交后可见的 PostgreSQL 通知；改期、取消和删除统一以会议 ID 为准';
COMMENT ON TRIGGER "human_interview_reminder_schedule_changed" ON "public"."studio_human_interview_meeting" IS '会议新增、预约时间或状态更新、删除后同步 TG 提醒调度记录；普通资料修改与提前入会不重复创建排期版本';

COMMENT ON COLUMN "public"."job_description"."duplicate_at_save" IS '保存当时是否存在同一工作区内岗位、部门、服务单位、来源表格、需求发起人、简历对接人均一致的其他记录；true 重复、false 不重复、NULL 尚未检查，不随其他岗位变化重新计算';
COMMENT ON COLUMN "public"."job_description"."duplicate_checked_at" IS '最近一次保存岗位时执行重复检查的时间；与 duplicate_at_save 同时更新，历史未检查记录为空';

COMMENT ON TABLE "public"."interview_media_room" IS '真人面试音视频留底房间档案；按 LiveKit 房间实例保存会议快照、采样运行状态和 Worker 租约，独立于普通日志长期保留';
COMMENT ON COLUMN "public"."interview_media_room"."room_sid" IS 'LiveKit 房间实例 SID，同时为档案主键；同一业务会议重建房间可形成多个档案';
COMMENT ON COLUMN "public"."interview_media_room"."room_name" IS 'LiveKit 房间业务名称';
COMMENT ON COLUMN "public"."interview_media_room"."meeting_id" IS '关联真人面试会议 ID；不随会议删除级联清除';
COMMENT ON COLUMN "public"."interview_media_room"."meeting_title" IS '会议标题快照，后续房间登记时可更新';
COMMENT ON COLUMN "public"."interview_media_room"."organization_id" IS '会议所属工作区 ID 快照';
COMMENT ON COLUMN "public"."interview_media_room"."started_at" IS '留底房间档案首次建立时间，不等同于业务面试正式开始时间';
COMMENT ON COLUMN "public"."interview_media_room"."ended_at" IS '收到 LiveKit 房间结束通知时记录的时间；为空表示尚未确认房间结束';
COMMENT ON COLUMN "public"."interview_media_room"."status" IS '采样状态：waiting 等待采样、capturing 采样中、stopped 已停止、error 采样异常';
COMMENT ON COLUMN "public"."interview_media_room"."error_code" IS '最近一次房间采样停止时的错误代码，无错误时为空';
COMMENT ON COLUMN "public"."interview_media_room"."lease_owner" IS '当前持有房间采样租约的 Worker 实例标识，防止多个实例同时采样';
COMMENT ON COLUMN "public"."interview_media_room"."lease_until" IS '采样租约有效期；过期后其他 Worker 可接管，释放时清空';
COMMENT ON COLUMN "public"."interview_media_room"."heartbeat_at" IS '采样 Worker 最近领取或续租的心跳时间';
COMMENT ON TABLE "public"."interview_media_asset" IS '真人面试截图及短音频留底明细；每个参与者每个采样时间槽一条，保存文件元数据、设备环境和失败原因；文件存于私有存储，管理员清理后保留删除标记';
COMMENT ON COLUMN "public"."interview_media_asset"."id" IS '留底资料记录 ID，也是文件存储键中的唯一标识';
COMMENT ON COLUMN "public"."interview_media_asset"."meeting_id" IS '关联真人面试会议 ID；不随会议删除或普通日志过期而清除';
COMMENT ON COLUMN "public"."interview_media_asset"."room_sid" IS '采样所属的 LiveKit 房间实例 SID，对应 interview_media_room.room_sid';
COMMENT ON COLUMN "public"."interview_media_asset"."participant_sid" IS '本次采样的 LiveKit 参与者连接 SID，用于区分同一参与身份的不同连接';
COMMENT ON COLUMN "public"."interview_media_asset"."participant_identity" IS '采样对象的 LiveKit 参与身份，用于关联候选人或面试官';
COMMENT ON COLUMN "public"."interview_media_asset"."participant_name" IS '采样时的参与者显示名称快照';
COMMENT ON COLUMN "public"."interview_media_asset"."participant_role" IS '采样时的参与角色：candidate 候选人、host 主持人、interviewer 面试官、observer 旁听，无法解析时为 unknown';
COMMENT ON COLUMN "public"."interview_media_asset"."track_sid" IS '采样音频或摄像头轨道的 LiveKit SID；无轨道而跳过时可为空';
COMMENT ON COLUMN "public"."interview_media_asset"."kind" IS '留底类型：image 摄像头截图、audio 麦克风短音频片段';
COMMENT ON COLUMN "public"."interview_media_asset"."slot" IS '采样时间槽标识；与房间 SID、参与者 SID 和资料类型共同去重，避免多 Worker 重复留底';
COMMENT ON COLUMN "public"."interview_media_asset"."status" IS '资料状态：pending 采集中或上传中、ready 可查看、failed 采集失败、skipped 条件不满足而跳过、deleted 已由管理员清理';
COMMENT ON COLUMN "public"."interview_media_asset"."captured_at" IS '采样记录创建时间，即本次采样尝试开始时间';
COMMENT ON COLUMN "public"."interview_media_asset"."duration_ms" IS '实际音频片段时长，单位毫秒；截图或未成功采样时可为空';
COMMENT ON COLUMN "public"."interview_media_asset"."byte_size" IS '文件大小，单位字节；尚未成功上传时为空';
COMMENT ON COLUMN "public"."interview_media_asset"."content_type" IS '文件 MIME 类型，如 image/jpeg 或 audio/wav';
COMMENT ON COLUMN "public"."interview_media_asset"."storage_key" IS '私有存储中的文件对象键，不是公开访问 URL；采样前登记，清理后保留便于审计';
COMMENT ON COLUMN "public"."interview_media_asset"."storage_backend" IS '文件存储后端：r2 私有对象存储、local 本地开发目录；未产生文件时可为空';
COMMENT ON COLUMN "public"."interview_media_asset"."sha256" IS '文件内容的 SHA-256 摘要，用于完整性核对和相同文件比对，不是人脸或声纹识别结果';
COMMENT ON COLUMN "public"."interview_media_asset"."error_code" IS '采样失败或跳过原因代码，如静音、无轨道、订阅超时、采集或上传失败';
COMMENT ON COLUMN "public"."interview_media_asset"."environment" IS '采样连接的设备环境快照 JSON：attemptId、visitId、tabId、browserId、fingerprint、fingerprintVersion、ip、ipSource、userAgent；按连接和访问关联，缺失字段不推断，标识不能单独证明真实身份';
COMMENT ON COLUMN "public"."interview_media_asset"."deleted_at" IS '管理员成功清理文件并标记删除的时间；未清理时为空';
COMMENT ON COLUMN "public"."interview_media_asset"."deleted_by" IS '执行资料清理的平台管理员用户 ID；未清理时为空';
COMMENT ON TABLE "public"."interview_media_access" IS '真人面试留底资料管理员访问审计；记录资料读取和成功清理操作，独立长期保留';
COMMENT ON COLUMN "public"."interview_media_access"."id" IS '访问审计记录主键';
COMMENT ON COLUMN "public"."interview_media_access"."asset_id" IS '被查看或清理的留底资料 ID，对应 interview_media_asset.id';
COMMENT ON COLUMN "public"."interview_media_access"."actor_id" IS '执行操作的平台管理员用户 ID';
COMMENT ON COLUMN "public"."interview_media_access"."action" IS '操作类型：view 读取资料内容、delete 成功清理资料';
COMMENT ON COLUMN "public"."interview_media_access"."created_at" IS '访问或清理审计记录创建时间';
